import numpy as np

def relu(x):
    return np.maximum(0, x)   # 음수는 0, 양수는 그대로

# (Michael 내적, Jordan 내적) 네 가지 경우
cases = {'Michael Jordan': (1, 1), 'Michael Phelps': (1, 0),
         'Alexis Jordan': (0, 1), '관계없음': (0, 0)}
for name, (m, j) in cases.items():
    before = m + j - 1        # 행렬 곱 + 편향 −1
    print(f'{name:15s} 곱+편향={before:2d}  ReLU 뒤={relu(before)}')
# Michael Jordan 만 1, 나머지는 0 → AND 문
